const pinDocumentSendEvidenceVersions = `-- name: PinDocumentSendEvidenceVersions :one
UPDATE documents
SET pdf_storage_version_id = CASE
        WHEN pdf_storage_key IS NULL THEN NULL
        ELSE COALESCE(pdf_storage_version_id, $1::text)
    END,
    rendered_pdf_version_id = CASE
        WHEN rendered_pdf_key IS NULL THEN NULL
        ELSE COALESCE(rendered_pdf_version_id, $2::text)
    END,
    evidence_version_pins_required = TRUE,
    updated_at = now()
WHERE id = $3
  AND org_id = $4
  AND status IN ('sealing','sent','in_progress','finalizing')
  AND deleted_at IS NULL
  AND (
    (pdf_storage_key IS NULL AND $1::text IS NULL)
    OR (
      pdf_storage_key IS NOT NULL
      AND NULLIF($1::text, '') IS NOT NULL
      AND (pdf_storage_version_id IS NULL OR pdf_storage_version_id = $1::text)
    )
  )
  AND (
    (rendered_pdf_key IS NULL AND $2::text IS NULL)
    OR (
      rendered_pdf_key IS NOT NULL
      AND NULLIF($2::text, '') IS NOT NULL
      AND (rendered_pdf_version_id IS NULL OR rendered_pdf_version_id = $2::text)
    )
  )
RETURNING id, org_id, template_id, name, status, routing_mode, source_kind, blocks_json, variables_json, rendered_pdf_key, rendered_pdf_sha, pdf_storage_key, pdf_sha256, final_pdf_key, final_pdf_sha, audit_cert_key, expires_at, sent_at, completed_at, sender_id, metadata, created_at, updated_at, parent_envelope_id, envelope_position, is_envelope, metadata_redaction_report, routing_tier, negotiation_enabled, bilingual_target_lang, lawful_basis, deleted_at, default_locale, requires_signature, audit_payload_key, audit_payload_sha256, audit_signature_key, audit_signature_sha256, pdf_storage_version_id, rendered_pdf_version_id, final_pdf_version_id, audit_cert_sha256, audit_cert_version_id, audit_payload_version_id, audit_signature_version_id, evidence_version_pins_required, completion_effective_at, completion_effective_at_bound, finalization_retain_until, article13_notice_epoch_at, article13_notice_schema, article13_notice_epoch_v61_committed
`

type PinDocumentSendEvidenceVersionsParams struct {
	PdfStorageVersionID  pgtype.Text `json:"pdf_storage_version_id"`
	RenderedPdfVersionID pgtype.Text `json:"rendered_pdf_version_id"`
	ID                   uuid.UUID   `json:"id"`
	OrgID                uuid.UUID   `json:"org_id"`
}

// A pre-VersionId document may already be active or enter sealing with
// digest-only source/rendered commitments. Resolve those versions once, then
// persist the pins while the document is non-editable. Send invokes this before
// retention_started_at; finalization invokes it before any source read. A retry
// may supply the same values but can never replace an existing pin.
func (q *Queries) PinDocumentSendEvidenceVersions(ctx context.Context, arg PinDocumentSendEvidenceVersionsParams) (*Document, error) {
	row := q.db.QueryRow(ctx, pinDocumentSendEvidenceVersions,
		arg.PdfStorageVersionID,
		arg.RenderedPdfVersionID,
		arg.ID,
		arg.OrgID,
	)
	var i Document
	err := row.Scan(
		&i.ID,
		&i.OrgID,
		&i.TemplateID,
		&i.Name,
		&i.Status,
		&i.RoutingMode,
		&i.SourceKind,
		&i.BlocksJson,
		&i.VariablesJson,
		&i.RenderedPdfKey,
		&i.RenderedPdfSha,
		&i.PdfStorageKey,
		&i.PdfSha256,
		&i.FinalPdfKey,
		&i.FinalPdfSha,
		&i.AuditCertKey,
		&i.ExpiresAt,
		&i.SentAt,
		&i.CompletedAt,
		&i.SenderID,
		&i.Metadata,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.ParentEnvelopeID,
		&i.EnvelopePosition,
		&i.IsEnvelope,
		&i.MetadataRedactionReport,
		&i.RoutingTier,
		&i.NegotiationEnabled,
		&i.BilingualTargetLang,
		&i.LawfulBasis,
		&i.DeletedAt,
		&i.DefaultLocale,
		&i.RequiresSignature,
		&i.AuditPayloadKey,
		&i.AuditPayloadSha256,
		&i.AuditSignatureKey,
		&i.AuditSignatureSha256,
		&i.PdfStorageVersionID,
		&i.RenderedPdfVersionID,
		&i.FinalPdfVersionID,
		&i.AuditCertSha256,
		&i.AuditCertVersionID,
		&i.AuditPayloadVersionID,
		&i.AuditSignatureVersionID,
		&i.EvidenceVersionPinsRequired,
		&i.CompletionEffectiveAt,
		&i.CompletionEffectiveAtBound,
		&i.FinalizationRetainUntil,
		&i.Article13NoticeEpochAt,
		&i.Article13NoticeSchema,
		&i.Article13NoticeEpochV61Committed,
	)
	return &i, err
}
